'use strict';
let zenReturnLocation=null,zenCalendarDay=today(),zenScheduleUndo=null;
const zenUsabilityGo=go;
go=function(next,...args){if(next==='focus'&&view!=='focus')zenReturnLocation={view,active,x:scrollX,y:scrollY,board:document.querySelector('.board')?.scrollLeft||0};return zenUsabilityGo(next,...args);};
function zenLeaveFocus(){zenReturnLocation=null;_WF.focus=null;go('focus');scrollTo(0,0);}
function zenConfirmFocusExit(){if(document.querySelector('.zen-focus-exit-dialog'))return;modal('<div class="zen-focus-exit-confirm"><span class="zen-focus-exit-mark" aria-hidden="true">✦</span><h2>Kết thúc phiên tập trung?</h2><p>Bạn đã hoàn thành được một phần công việc. Hãy chọn tiếp tục ở lại hoặc kết thúc phiên này.</p><div class="zen-focus-exit-actions"><button type="button" class="btn" data-zen-focus-stay><span aria-hidden="true">◎</span> Ở lại</button><button type="button" class="btn primary" data-zen-focus-leave><span aria-hidden="true">↩</span> Thoát</button></div></div>',null,true);const dialog=document.querySelector('#editor');dialog.classList.add('zen-focus-exit-dialog');dialog.addEventListener('close',()=>dialog.classList.remove('zen-focus-exit-dialog'),{once:true});dialog.querySelector('[data-zen-focus-stay]').onclick=()=>dialog.close();dialog.querySelector('[data-zen-focus-leave]').onclick=()=>{dialog.close();zenLeaveFocus();};}
document.addEventListener('click',e=>{if(e.target.closest('[data-wf-focus-exit]')){e.preventDefault();e.stopImmediatePropagation();zenConfirmFocusExit();return;}const day=e.target.closest('[data-zen-select-day]');if(day){zenCalendarDay=day.dataset.zenSelectDay;render();}if(e.target.closest('[data-zen-schedule-undo]')&&zenScheduleUndo){const p=project(zenScheduleUndo.pid),t=p?.tasks.find(t=>t.id===zenScheduleUndo.id);if(t&&JSON.stringify([t.start,t.end,t.due])===zenScheduleUndo.after){Object.assign(t,zenScheduleUndo.before);save();zenScheduleUndo=null;render();notify('Đã hoàn tác lịch.');}else notify('Lịch đã thay đổi tiếp; hãy mở công việc để kiểm tra.');}},true);
const zenFocusNoteState=new Map();
document.addEventListener('toggle',e=>{if(!e.target.matches('.zen-focus-notes,.zen-focus-manage')||!_WF.focus)return;const key=_WF.focus.p+':'+_WF.focus.t;const state=zenFocusNoteState.get(key)||{};state[e.target.classList.contains('zen-focus-manage')?'manage':'notes']=e.target.open;zenFocusNoteState.set(key,state);},true);
const zenUsabilityFocus=wfPaintFocus;
wfPaintFocus=function(){zenUsabilityFocus();if(view!=='focus'||!_WF.focus)return;const aside=document.querySelector('.wf-focus-workspace>aside');if(!aside)return;const details=document.createElement('details');details.className='zen-focus-notes';const noteState=zenFocusNoteState.get(_WF.focus.p+':'+_WF.focus.t)||{};details.open=!!noteState.notes;const summary=document.createElement('summary');summary.textContent='Ghi chú liên quan';aside.before(details);details.append(summary,aside);const actions=aside.querySelector('.wf-focus-note-actions');if(actions){const manage=document.createElement('details');manage.className='zen-focus-manage';manage.open=!!noteState.manage;manage.innerHTML='<summary>Quản lý ghi chú liên kết</summary>';actions.before(manage);manage.append(actions);aside.querySelectorAll('[data-focus-unlink]').forEach(button=>manage.append(button));}};
const zenUsabilityCalendar=workCalendar;
workCalendar=function(){const html=zenUsabilityCalendar();if(!matchMedia('(max-width:700px)').matches)return html;const template=document.createElement('template');template.innerHTML=html;template.content.querySelectorAll('.month-cell').forEach(cell=>{const time=cell.querySelector('time');if(!time)return;const day=time.dateTime,count=cell.querySelectorAll('.month-event').length;cell.querySelectorAll('.month-event').forEach(event=>event.remove());const button=document.createElement('button');button.type='button';button.dataset.zenSelectDay=day;button.className='zen-calendar-date';button.setAttribute('aria-pressed',String(day===zenCalendarDay));button.setAttribute('aria-label',day+', '+count+' công việc');button.textContent=time.textContent+(count?' · '+count:'');time.replaceWith(button);});const monthPrefix=calendarYear+'-'+String(calendarMonth+1).padStart(2,'0');if(!zenCalendarDay.startsWith(monthPrefix))zenCalendarDay=monthPrefix+'-01';const events=zenCalendarDayEvents(scheduleEvents(),zenCalendarDay);return template.innerHTML+'<section class="panel zen-day-agenda"><h2>Lịch ngày '+esc(dateLabel(zenCalendarDay))+'</h2>'+(events.map(t=>'<button type="button" class="zen-agenda-task" data-task="'+esc(t.id)+'" data-pid="'+esc(t.project.id)+'"><strong>'+esc(t.title)+'</strong><span>'+esc(t.project.name)+' · '+esc(zenCalendarEventTime(t,zenCalendarDay)||'Cả ngày')+'</span><span>'+taskPct(t)+'% hoàn thành · Đổi lịch trong chi tiết</span></button>').join('')||'<p>Chưa có công việc trong ngày này.</p>')+'</section>';};
const zenUsabilityFinish=finishGanttDrag;
finishGanttDrag=function(commit){const g=ganttPointer,before=g&&{start:g.task.start,end:g.task.end,due:g.task.due};zenUsabilityFinish(commit);if(commit&&g&&g.days){const t=project(g.pid)?.tasks.find(t=>t.id===g.id);if(t&&JSON.stringify([t.start,t.end,t.due])!==g.original){zenScheduleUndo={pid:g.pid,id:g.id,before,after:JSON.stringify([t.start,t.end,t.due])};document.querySelector('#main')?.insertAdjacentHTML('afterbegin','<aside class="zen-schedule-feedback" role="status">Đã đổi lịch: '+esc(t.title)+' · '+esc(dateLabel(t.start?.slice(0,10)||t.due))+' → '+esc(dateLabel(t.end?.slice(0,10)||t.due))+' <button type="button" class="btn" data-zen-schedule-undo>Hoàn tác</button><button type="button" class="btn" data-task="'+esc(t.id)+'" data-pid="'+esc(g.pid)+'">Chỉnh ngày</button></aside>');}}};
const zenUsabilitySync=syncStatus;
syncStatus=function(message,kind){const raw=String(message||''),conflict=/xung đột|hợp nhất/i.test(raw);let label=raw;if(conflict)label='Xung đột · Xem và chọn bản cần giữ';else if(kind==='offline'||!navigator.onLine)label='Ngoại tuyến · Bạn vẫn có thể chỉnh sửa';else if(kind==='error')label='Chưa đồng bộ được · '+raw.replace(/^[⚠●]\s*/,'');else if(/đang đồng bộ/i.test(raw))label='Đang đồng bộ…';else if(/đã lưu trên máy|tiếp tục đồng bộ/i.test(raw))label='Đã lưu trên thiết bị · Chờ đồng bộ';else if(/đã đồng bộ|đã cập nhật từ/i.test(raw))label='Đã đồng bộ lúc '+new Date().toLocaleTimeString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour:'2-digit',minute:'2-digit'});zenUsabilitySync(label,kind);let alert=document.querySelector('#zen-sync-feedback');if(kind==='error'||conflict){if(!alert){alert=document.createElement('aside');alert.id='zen-sync-feedback';alert.setAttribute('role','status');document.querySelector('.topbar')?.after(alert);}alert.replaceChildren();const text=document.createElement('span');text.textContent=label;const retry=document.createElement('button');retry.type='button';retry.className='btn';retry.textContent=conflict?'Xem các bản dữ liệu':'Thử lại';retry.onclick=()=>conflict?accountPanel():flushCloud(true);alert.append(text,retry);}else if(kind==='saved'||/đã đồng bộ|đã cập nhật từ/i.test(raw))alert?.remove();};
